def count_palindrome_insertions(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i][j - 1] + dp[i + 1][j] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return sum(dp[0][i] - 1 for i in range(n))

