from heapq import nlargest

def organize_runners(n, k):
    if n > (k // 2):
        return -1

    runners = list(range(1, n + 1))
    track1 = nlargest(n - (k // 2), runners)
    track2 = runners[:n - (k // 2)]

    return binary_search_time(n, track1, track2, k)

def binary_search_time(n, track1, track2, k):
    timeout = True
    lower, upper = 0, n * (n + 1) // 2

    while timeout and lower <= upper:
        mid = (lower + upper) // 2
        runner_sum = sum(max(mid - runner_sum, runner) for runner_sum in binary_sum(track1, track2, mid))

        if runner_sum > k:
            upper = mid - 1
        else:
            timeout = False
            lower = mid + 1

    if timeout:
        return -1

    return max((runner_sum, track1, track2)) if runner_sum <= k else -1

def binary_sum(track1, track2, threshold):
    return sum(max(runner_sum, runner) for runner_sum in binary_sum_different(track1, track2, threshold))

def binary_sum_different(track1, track2, threshold):
    threshold_track = sorted(track1 + track2, key=lambda x: x * 2)
    runner_sum = 0
    for t in threshold_track:
        for _ in range(min(t, threshold)):
            runner_sum += runner_sum + min(t, threshold)
        threshold -= min(t, threshold)
    return runner_sum

print(organize_runners(int(input()), int(input())))
