import sys
from typing import List

class PocketFilter:
    def __init__(self, pockets: List[int]):
        self.pockets = sorted(pockets)

    def process(self):
        old_size = 0
        for i in range(len(self.pockets)):
            new_size = min(old_size // 5, self.pockets[i])
            new_pocket, old_pocket = max(new_size, 0), min(old_size, self.pockets[i] - new_size)
            self.pockets = self.pockets[:i] + [new_pocket] + self.pockets[i:]
            old_size = self.pockets[-1]

    def get_cell(self, idx: int) -> int:
        if self.pockets:
            return self.pockets[-1] - idx
        return 0

    def get_cell_with_size(self, size: int) -> int:
        for pocket, pocket_idx in enumerate(self.pockets):
            if pocket_idx <= size:
                self.pockets[pocket_idx - 1] -= size
                return pocket
        return -1

def solve(pockets: List[int], queries: List[List[int]]) -> List[int]:
    pf = PocketFilter(pockets)
    for q in queries:
        q_x, q_k = q
        x, k = q_x, q_k
        if q_x == 0:
            for _ in range(k):
                pf.process()
        else:
            pocket_idx = pf.get_cell_with_size(k - 1) + 1
            q_y = 1 + sum(range(k - pocket_idx, k))
            if x - 1 >= 0 and x - 1 < q_y - q_x:
                q_y = q_x + (x - 1) // (k - 1) * (q_y - q_x)
                q_x = x - 1
                if q_y - x > 1:
                    q_y -= (q_y - x) // (k - 1) * (q_y - x)
            returns.append(q_y)
    return returns

