def restore_diary(n, diary):
    counts = Counter(diary)
    max_books_read = 0

    def dfs(start_day):
        nonlocal max_books_read
        if start_day == n:
            return True

        max_books_read = max(max_books_read, sum(counts[i] for i in range(start_day, n) if i - start_day < 5))

        if counts[start_day] == 0:
            return False

        last_day = [0] * (5 + 1)

        for i in range(start_day + 1, n + 1):
            if counts[i] == 0:
                if all(last_day[j] < i - start_day + j - 1 for j in range(1, 6)):
                    last_day[last_day.index(max(last_day)) + 1] = i
                    if dfs(i): return True
                    last_day[last_day.index(max(last_day)) + 1] = 0

        return not dfs(start_day + 1)

    if not dfs(0):
        return -1

    result = [0] * n
    current_booking = {}

    for i in range(n):
        while True:
            fd = result[i - 1] if i else 0
            if counts[fd] or not current_booking:
                break
            result[i], counts[result[i]] = current_booking.pop(min(current_booking)), 0

            for j in range(5):
                if j + fd not in result or j + fd >= n or (j + fd in result and result[j + fd] < result[i]):
                    result[j + fd] = j + fd
                    if len(result) > 5: result = result[:5]
                    break

            counts[result[i]] += 1

        current_booking = max(current_booking, {fd: count for fd, count in enumerate(result) if results.count(fd) == count})

    return max_books_read, result

