class DisjointSet:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x, root_y = self.find(x), self.find(y)
        if root_x == root_y:
            return
        if self.size[root_x] > self.size[root_y]:
            root_x, root_y = root_y, root_x
        self.parent[root_x] = root_y
        self.size[root_y] += self.size[root_x]

def evaluate_sums(query_count, indices, values, queries):
    n, m = len(indices) + 1, query_count
    ds = DisjointSet(n)
    for i, value in enumerate(values + [0]):
        ds.union(indices[i] + 1, len(indices) + 1)
        s = 0
        for j in range(1, n):
            ds.union(j, (j - 1) + 1)
            if i and indices[j - 1] < indices[j]:  # Include overlapping elements
                ds.union(indices[j - 1] + 1, indices[j] + 1)
            ds.union(len(indices), 2 * n - ds.find(j))
            s = (s + value) % (10**9 + 9)
    queries = [complex(1j)**i for i in queries]
    return [int(round(1j * s * complex(1, -2) % (10**9 + 9).real)) for s in s // (1j * complex(n, -n) % (10**9 + 9).real)]

