import sys

def is_valid_ordering(topics, prerequisites, target):
    # Check if we can order the topics such that compiling the prerequisites
    # goes from lowest precedence to highest precedence.
    comp_order = list(range(len(prerequisites) + 1))
    for i in range(1, len(prerequisites) + 1):
        for j in range(i - 1, -1, -1):
            if topics[comp_order[i]] < topics[comp_order[j]]:
                comp_order.insert(i, comp_order[j])
                break
        else:
            comp_order.insert(i, comp_order[-1])
    return all(prerequisites[i] <= prerequisites[i + 1] for i in range(len(prerequisites)))

