import math
from collections import defaultdict

def max_lap_length(n, x, y, a, q):
    max_length = [0] * q
    divisor_dict = defaultdict(set)

    for i in range(1, len(a)):
        l = a[i] - a[i-1]
        divisor_dict[l].add(divide_by_(l, i, n, y, x))

    for i in range(n):
        divisor_set = divisor_dict[y - t(i, x)]
        if divisor_set:
            for divisor in divisor_set:
                if divisor != -1:
                    max_length[i] = max(max_length[i], divisor)

    return max_length

def t(a, b):
    return (b - a) // (a * 3 ** (1/2))**(1/2) * 3 ** (1/2)

def divide_by_(l, i, n, y, x):
    while y:
        if l % 2 == 0 and (y - t(i, x) * (l // 2) < y // 2 or x - t(i, x) * l // 2 < t(i + 1, x) - t(i, x)):
            return -1
        if l % 4 == 0 and x - t(i, x) * (l // 4) < y // 4 or y - t(i, x) * l // 4 < t(i + 1, x) - t(i, x):
            return -1
        else:
            l //= 2
    return l

def process_cases():
    t = int(input().strip())

    for _ in range(t):
        n, x, y = list(map(int, input().split()))
        a = list(map(int, input().split()))
        q = int(input())
