from collections import deque

def max_total_time(n, k):
    if 2 * n > k:
        return -1
    q = k - 2 * n
    if q & 1:
        return k
    order = [i // 2 for i in range(1, n + 1)]
    left, right = deque(order), deque(order[::-1])
    time = 0
    while left and right:
        max_val = max(left[0], right[0])
        if max_val > n:
            return -1
        time += max_val
        if left[0] != right[0]:
            time += max_val
        if len(left) > q:
            time += left.popleft()
        if len(right) > q:
            time += right.popleft()
    return time

# Example usage
print(max_total_time(5, 20))
