    for book, count in book_counts.items():
        temp_count += count
        if temp_count > max_books:
            max_books = temp_count
            first_day = book
        elif temp_count == max_books:
            max_books = temp_count

    if max_books > 5:
        return -1
    else:
        first_books = [first_day] * max_books
        for book, count in book_counts.items():
            if book < first_day:
                first_books[:book] = [book] * count
            elif book < first_day + max_books:
                first_books[book - max_books] = book

        return max_books, first_books

